@inject ISettingsService SettingsService

<div class="security-section">
    <h4 class="mb-4">Security Settings</h4>

    @if (_loading)
    {
        <div class="text-center py-4"><div class="spinner-border text-primary" role="status"></div></div>
    }
    else
    {
        <ChangePasswordPanel OnChangePassword="HandleChangePasswordAsync" />

        <div class="card mb-4">
            <div class="card-body">
                <div class="d-flex align-items-center justify-content-between">
                    <div>
                        <h6 class="mb-1">🛡️ Two-Factor Authentication</h6>
                        <p class="text-muted small mb-0">Add an extra layer of security to your account.</p>
                    </div>
                    <div class="d-flex align-items-center gap-2">
                        <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                        <div class="form-check form-switch mb-0">
                            <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" />
                        </div>
                    </div>
                </div>
                @if (_lastPasswordChange.HasValue)
                {
                    <hr />
                    <p class="text-muted small mb-0">
                        Last password change: <strong>@_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</strong>
                    </p>
                }
            </div>
        </div>

        <ActiveSessionsTable Sessions="_sessions" CurrentSessionId="sess-1" OnRevoke="HandleRevokeAsync" />
    }
</div>

@code {
    private bool _loading = true;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = [];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = [.. settings.Sessions];
        _loading = false;
    }

    private async Task HandleChangePasswordAsync((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        _lastPasswordChange = DateTime.UtcNow;
    }

    private async Task HandleRevokeAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _sessions = _sessions.Where(s => s.Id != sessionId).ToList();
    }
}

