    {
        <div class="text-center py-4"><div class="spinner-border text-primary" role="status"></div></div>
    }
    else
    {
        <div class="row">
            <div class="col-md-7">
                <div class="card mb-4">
                    <div class="card-body">
                        <h6 class="card-title mb-3">🎨 Theme</h6>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check mb-2">
                                <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                                       value="@theme" checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-4">
                    <div class="card-body">
                        <h6 class="card-title mb-3">🔤 Font Size</h6>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                                       value="@size" checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-4">
                    <div class="card-body">
                        <h6 class="card-title mb-3">🌐 Language</h6>
                        <select class="form-select" @bind="_language">
                            @foreach (var lang in Languages)
                            {
                                <option value="@lang">@lang</option>
                            }
                        </select>
                    </div>
                </div>

                <div class="card mb-4">
                    <div class="card-body">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                            <label class="form-check-label" for="compactMode">
                                <strong>Compact Mode</strong>
                                <br /><small class="text-muted">Reduce spacing and padding throughout the interface</small>
                            </label>
                        </div>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @if (_saving)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Save
                </button>

                @if (_showSuccess)
                {
                    <div class="alert alert-success alert-dismissible fade show mt-3" role="alert">
                        ✅ Appearance settings saved!
                        <button type="button" class="btn-close" @onclick="() => _showSuccess = false"></button>
                    </div>
                }
            </div>

            <div class="col-md-5">
                <div class="card">
                    <div class="card-header"><h6 class="mb-0">Live Preview</h6></div>
                    <div class="card-body preview-area @PreviewThemeClass" style="@PreviewStyle">
                        <div class="preview-header mb-2" style="@PreviewHeaderStyle">
                            <strong>Settings Dashboard</strong>
                        </div>
                        <p class="mb-2" style="@PreviewFontStyle">
                            This is how your interface will look with the selected settings.
                        </p>
                        <div class="d-flex gap-2 mb-2">
                            <span class="badge" style="@PreviewBadgeStyle">Badge</span>
                            <span class="badge" style="@PreviewBadgeSecondaryStyle">Status</span>
                        </div>
                        <div class="preview-card @(_compactMode ? "compact" : "")" style="@PreviewCardStyle">
                            <small style="@PreviewFontStyle">
                                @(_compactMode ? "Compact spacing applied" : "Normal spacing applied")
                                — Language: @_language
                            </small>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    private static readonly string[] Languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Korean", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;
        await SettingsService.SaveAppearanceAsync(new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        _saving = false;
        _showSuccess = true;
    }

    private string PreviewThemeClass => _theme switch
    {
        "Dark" => "preview-dark",
        _ => "preview-light"
    };

    private string PreviewStyle => _theme switch
    {
        "Dark" => "background-color: #1e1e2e; color: #cdd6f4; border-color: #45475a;",
        _ => "background-color: #ffffff; color: #212529;"
    };

    private string PreviewHeaderStyle => _theme switch
    {
        "Dark" => "color: #89b4fa;",
        _ => "color: #0d6efd;"
    };

    private string PreviewFontStyle => _fontSize switch
    {
        "Small" => "font-size: 0.8rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 0.95rem;"
    };

    private string PreviewBadgeStyle => _theme switch
    {
        "Dark" => "background-color: #89b4fa; color: #1e1e2e;",
        _ => "background-color: #0d6efd; color: #fff;"
    };

    private string PreviewBadgeSecondaryStyle => _theme switch
    {
        "Dark" => "background-color: #45475a; color: #cdd6f4;",
        _ => "background-color: #6c757d; color: #fff;"
    };

    private string PreviewCardStyle
    {
        get
        {
            var padding = _compactMode ? "padding: 0.35rem 0.5rem;" : "padding: 0.75rem;";
            var border = _theme == "Dark"
                ? "border: 1px solid #45475a; background-color: #313244; border-radius: 0.375rem;"
                : "border: 1px solid #dee2e6; background-color: #f8f9fa; border-radius: 0.375rem;";
            return $"{padding} {border}";
        }
    }
}

